// Tier-specific base time windows for "recently used"
#define BASE_RECENT_COLD_NS      30000000ULL    // 30 ms (aggressive for cold tier)
#define BASE_RECENT_WARM_NS      50000000ULL    // 50 ms (moderate)
#define BASE_RECENT_HOT_NS       100000000ULL   // 100 ms (protective for hot tier)

// Tier-specific base time windows for working set
#define BASE_WORKING_SET_COLD_NS 400000000ULL   // 400 ms (aggressive)
#define BASE_WORKING_SET_WARM_NS 800000000ULL   // 800 ms (moderate)
#define BASE_WORKING_SET_HOT_NS  1200000000ULL  // 1.2 s (protective)

// Network idle timeout
#define NET_IDLE_TIMEOUT_NS      5000000000ULL  // 5 s
// Access count threshold for hot
#define HOT_ACCESS_THRESHOLD     4
// Burst detection: inter-arrival time threshold (usec)
#define BURST_THRESHOLD_US       5000ULL        // 5 ms

// Tier-specific congestion scaling factors
#define CONGESTION_SCALE_COLD    500ULL         // cold scales slower with congestion
#define CONGESTION_SCALE_WARM    500ULL         // warm scales moderately
#define CONGESTION_SCALE_HOT     250ULL         // hot scales faster with congestion

// -- Helper: Compute burst detection score ---
// Returns true if we're in a burst (packets arriving quickly)
static __always_inline bool is_burst(u64 now) {
    if (net_prev_packet_ts == 0)
        return false;

    u64 inter_arrival_ns = (now > net_prev_packet_ts) ?
        (now - net_prev_packet_ts) : 0;

    // Consider it a burst if packets arrive within 5ms of each other
    return (inter_arrival_ns < 5000000ULL);
}

// -- Helper: Compute network congestion score (0-1000 scale, higher = more congested) --
static __always_inline u32 compute_congestion_score(void) {
    u32 score = 0;

    // Factor 1: RTT level (normalize net_srtt_us to 0-400 points)
    // High RTT means each cache miss is costly
    u32 rtt_us = net_srtt_us >> 3;  // kernel stores srtt<<3, divide by 8
    if (rtt_us > 100000)
        score += 400;  // RTT > 100ms = heavy congestion
    else if (rtt_us > 50000)
        score += 300;
    else if (rtt_us > 20000)
        score += 200;
    else if (rtt_us > 5000)
        score += 100;

    // Factor 2: Jitter / mdev (0-250 points)
    u32 mdev_us = net_mdev_us >> 3;
    if (mdev_us > 20000)
        score += 250;
    else if (mdev_us > 10000)
        score += 200;
    else if (mdev_us > 5000)
        score += 150;
    else if (mdev_us > 1000)
        score += 100;

    // Factor 3: Retransmissions (0-200 points)
    if (net_retrans_out > 5 || net_lost > 0)
        score += 200;
    else if (net_total_retrans > 10)
        score += 150;
    else if (net_total_retrans > 0)
        score += 50;

    // Factor 4: Congestion window pressure (0-150 points)
    // Small cwnd relative to packets_out = bottleneck
    if (net_packets_out > 0 && net_snd_cwnd > 0) {
        if (net_packets_out * 2 > net_snd_cwnd)
            score += 150;
        else if (net_packets_out * 3 > net_snd_cwnd)
            score += 100;
    }

    return (score > 1000) ? 1000 : score;
}

// -- Helper: Compute tier-specific adaptive recent windows based on network conditions --
static __always_inline u64 get_adaptive_recent_window_cold(u32 congestion) {
    // Cold tier: aggressive eviction even during congestion
    // Scale from BASE_RECENT_COLD_NS (30ms) up to ~60ms
    u64 window = BASE_RECENT_COLD_NS;
    window += (BASE_RECENT_COLD_NS * congestion) / CONGESTION_SCALE_COLD;
    return (window > 60000000ULL) ? 60000000ULL : window;
}

static __always_inline u64 get_adaptive_recent_window_warm(u32 congestion) {
    // Warm tier: moderate congestion scaling
    // Scale from BASE_RECENT_WARM_NS (50ms) up to ~150ms
    u64 window = BASE_RECENT_WARM_NS;
    window += (BASE_RECENT_WARM_NS * congestion) / CONGESTION_SCALE_WARM;
    return (window > 150000000ULL) ? 150000000ULL : window;
}

static __always_inline u64 get_adaptive_recent_window_hot(u32 congestion) {
    // Hot tier: stronger congestion scaling for protection
    // Scale from BASE_RECENT_HOT_NS (100ms) up to ~300ms
    u64 window = BASE_RECENT_HOT_NS;
    window += (BASE_RECENT_HOT_NS * congestion) / CONGESTION_SCALE_HOT;
    return (window > 300000000ULL) ? 300000000ULL : window;
}

static __always_inline u64 get_adaptive_working_set_window_cold(u32 congestion) {
    // Cold tier: aggressive working set window
    u64 window = BASE_WORKING_SET_COLD_NS;
    window += (BASE_WORKING_SET_COLD_NS * congestion) / CONGESTION_SCALE_COLD;
    return (window > 800000000ULL) ? 800000000ULL : window;
}

static __always_inline u64 get_adaptive_working_set_window_warm(u32 congestion) {
    // Warm tier: moderate working set window
    u64 window = BASE_WORKING_SET_WARM_NS;
    window += (BASE_WORKING_SET_WARM_NS * congestion) / CONGESTION_SCALE_WARM;
    return (window > 1600000000ULL) ? 1600000000ULL : window;
}

static __always_inline u64 get_adaptive_working_set_window_hot(u32 congestion) {
    // Hot tier: protective working set window
    u64 window = BASE_WORKING_SET_HOT_NS;
    window += (BASE_WORKING_SET_HOT_NS * congestion) / CONGESTION_SCALE_HOT;
    return (window > 2400000000ULL) ? 2400000000ULL : window;
}

// -- Helper: Compute folio eviction score (higher = keep it) --
// tier parameter: 0=cold, 1=warm, 2=hot (used for tier-specific window selection)
static __always_inline u32 compute_folio_score(struct net_folio_metadata *meta,
                                                u64 now, u32 congestion,
                                                bool in_burst, bool session_active,
                                                u32 tier) {
    u32 score = 0;

    if (!meta)
        return 0;

    u64 age_ns = (now > meta->last_access_ts) ? (now - meta->last_access_ts) : 0;

    // Select tier-specific time windows
    u64 recent_window, working_set_window;
    if (tier == 2) {  // hot
        recent_window = get_adaptive_recent_window_hot(congestion);
        working_set_window = get_adaptive_working_set_window_hot(congestion);
    } else if (tier == 1) {  // warm
        recent_window = get_adaptive_recent_window_warm(congestion);
        working_set_window = get_adaptive_working_set_window_warm(congestion);
    } else {  // cold
        recent_window = get_adaptive_recent_window_cold(congestion);
        working_set_window = get_adaptive_working_set_window_cold(congestion);
    }

    // Recency score (0-500 points)
    // Linear decay from 500 (just accessed) to 0 (beyond recent window)
    if (age_ns < recent_window) {
        score += 500 - (500 * age_ns) / recent_window;
    }

    // Frequency score (0-300 points)
    // Logarithmic: access_count 1→50, 2→100, 3→150, 4+→300
    if (meta->access_count >= 4)
        score += 300;
    else if (meta->access_count == 3)
        score += 150;
    else if (meta->access_count == 2)
        score += 100;
    else if (meta->access_count == 1)
        score += 50;

    // Burst protection bonus (0-200 points)
    // During bursts, protect the working set more aggressively
    if (in_burst && age_ns < working_set_window) {
        score += 200 - (200 * age_ns) / working_set_window;
    }

    // Congestion protection (0-100 points)
    // In high congestion, protect pages in working set more
    if (session_active && age_ns < working_set_window && congestion > 500) {
        score += (congestion - 500) / 5;  // 0-100 points
    }

    // Tier bonus: hot folios get extra protection
    if (meta->access_tier == 2)
        score += 150;
    else if (meta->access_tier == 1)
        score += 75;

    return score;
}

// -- Eviction callback for cold_list (most aggressive eviction) --
static int bpf_evict_cold_cb(int idx, struct cache_ext_list_node *node) {
    u64 now = bpf_ktime_get_ns();
    u64 key = (u64)node->folio;

    struct net_folio_metadata *meta =
        bpf_map_lookup_elem(&folio_metadata_map, &key);

    if (!meta)
        return CACHE_EXT_EVICT_NODE;

    if (folio_test_dirty(node->folio) || folio_test_writeback(node->folio))
        return CACHE_EXT_CONTINUE_ITER;

    // Cold list: evict cold folios that haven't been accessed recently
    if (meta->access_tier == 0) {
        u64 age_ns = (now > meta->last_access_ts) ?
            (now - meta->last_access_ts) : 0;
        if (age_ns > 500000000ULL)  // older than 500ms
            return CACHE_EXT_EVICT_NODE;
    }

    return CACHE_EXT_CONTINUE_ITER;
}

// -- Eviction callback for warm_list (moderate eviction) --
static int bpf_evict_warm_cb(int idx, struct cache_ext_list_node *node) {
    u64 now = bpf_ktime_get_ns();
    u64 key = (u64)node->folio;

    struct net_folio_metadata *meta =
        bpf_map_lookup_elem(&folio_metadata_map, &key);

    if (!meta)
        return CACHE_EXT_EVICT_NODE;

    if (folio_test_dirty(node->folio) || folio_test_writeback(node->folio))
        return CACHE_EXT_CONTINUE_ITER;

    u32 congestion = compute_congestion_score();
    bool session_active = (now - last_packet_ts) < NET_IDLE_TIMEOUT_NS;
    bool in_burst = is_burst(now);

    u32 score = compute_folio_score(meta, now, congestion, in_burst, session_active, 1);

    // Evict warm folios with low score
    if (score < 200)
        return CACHE_EXT_EVICT_NODE;

    return CACHE_EXT_CONTINUE_ITER;
}

// -- Eviction callback for hot_list (conservative eviction) --
static int bpf_evict_hot_cb(int idx, struct cache_ext_list_node *node) {
    u64 now = bpf_ktime_get_ns();
    u64 key = (u64)node->folio;

    struct net_folio_metadata *meta =
        bpf_map_lookup_elem(&folio_metadata_map, &key);

    if (!meta)
        return CACHE_EXT_EVICT_NODE;

    if (folio_test_dirty(node->folio) || folio_test_writeback(node->folio))
        return CACHE_EXT_CONTINUE_ITER;

    u32 congestion = compute_congestion_score();
    bool session_active = (now - last_packet_ts) < NET_IDLE_TIMEOUT_NS;
    bool in_burst = is_burst(now);

    u32 score = compute_folio_score(meta, now, congestion, in_burst, session_active, 2);

    // Only evict hot folios with very low score (highly protective)
    if (score < 100)
        return CACHE_EXT_EVICT_NODE;

    return CACHE_EXT_CONTINUE_ITER;
}

