// Network idle timeout
#define NET_IDLE_TIMEOUT_NS      5000000000ULL  // 5 s
// Access count threshold for hot
#define HOT_ACCESS_THRESHOLD     4
// Burst detection: inter-arrival time threshold (usec)
#define BURST_THRESHOLD_US       5000ULL        // 5 ms

// -- Access count decay constants -----------------------------------------------
// Base decay window: if a folio hasn't been accessed for this long, decay its access_count
#define BASE_DECAY_WINDOW_NS     500000000ULL   // 500 ms

// Tier-specific decay sensitivity (higher = slower decay)
#define DECAY_SENSITIVITY_COLD   1000ULL        // cold tier: fast decay
#define DECAY_SENSITIVITY_WARM   1500ULL        // warm tier: moderate decay
#define DECAY_SENSITIVITY_HOT    2000ULL        // hot tier: slow decay

// -- Helper: Update burst tracking state ---
// Updates consecutive_burst_packets based on current burst status
static __always_inline void update_burst_tracking(u64 now) {
    if (last_burst_check_ts == 0) {
        last_burst_check_ts = now;
        consecutive_burst_packets = 0;
        return;
    }

    u64 time_since_last_check = (now > last_burst_check_ts) ?
        (now - last_burst_check_ts) : 0;

    // Update burst counter based on inter-arrival time
    if (time_since_last_check < 5000000ULL) {  // within 5ms burst threshold
        if (consecutive_burst_packets < 20)  // cap at 20
            consecutive_burst_packets += 1;
    } else {
        // Reset if gap exceeds burst threshold
        consecutive_burst_packets = 0;
    }

    last_burst_check_ts = now;
}

// -- Helper: Compute burst detection score ---
// Returns true if we're in a burst (packets arriving quickly)
static __always_inline bool is_burst(u64 now) {
    if (net_prev_packet_ts == 0)
        return false;

    u64 inter_arrival_ns = (now > net_prev_packet_ts) ?
        (now - net_prev_packet_ts) : 0;

    // Consider it a burst if packets arrive within 5ms of each other
    return (inter_arrival_ns < 5000000ULL);
}

// -- Helper: Get sustained burst intensity (0-1000 scale) ---
// Returns intensity based on consecutive burst packets
static __always_inline u32 get_burst_intensity(void) {
    // Map consecutive_burst_packets to 0-1000 scale
    // 0-3 packets → 0 (not sustained)
    // 4-7 packets → 250 (light burst)
    // 8-11 packets → 500 (moderate burst)
    // 12+ packets → 1000 (heavy sustained burst)
    if (consecutive_burst_packets >= 12)
        return 1000;
    else if (consecutive_burst_packets >= 8)
        return 500;
    else if (consecutive_burst_packets >= 4)
        return 250;
    else
        return 0;
}

// -- Helper: Compute network congestion score (0-1000 scale, higher = more congested) --
static __always_inline u32 compute_congestion_score(void) {
    u32 score = 0;

    // Factor 1: RTT level (normalize net_srtt_us to 0-400 points)
    // High RTT means each cache miss is costly
    u32 rtt_us = net_srtt_us >> 3;  // kernel stores srtt<<3, divide by 8
    if (rtt_us > 100000)
        score += 400;  // RTT > 100ms = heavy congestion
    else if (rtt_us > 50000)
        score += 300;
    else if (rtt_us > 20000)
        score += 200;
    else if (rtt_us > 5000)
        score += 100;

    // Factor 2: Jitter / mdev (0-250 points)
    u32 mdev_us = net_mdev_us >> 3;
    if (mdev_us > 20000)
        score += 250;
    else if (mdev_us > 10000)
        score += 200;
    else if (mdev_us > 5000)
        score += 150;
    else if (mdev_us > 1000)
        score += 100;

    // Factor 3: Retransmissions (0-200 points)
    if (net_retrans_out > 5 || net_lost > 0)
        score += 200;
    else if (net_total_retrans > 10)
        score += 150;
    else if (net_total_retrans > 0)
        score += 50;

    // Factor 4: Congestion window pressure (0-150 points)
    // Small cwnd relative to packets_out = bottleneck
    if (net_packets_out > 0 && net_snd_cwnd > 0) {
        if (net_packets_out * 2 > net_snd_cwnd)
            score += 150;
        else if (net_packets_out * 3 > net_snd_cwnd)
            score += 100;
    }

    return (score > 1000) ? 1000 : score;
}

// -- Helper: Compute adaptive decay window based on congestion --
// Higher congestion → slower decay (wider window)
static __always_inline u64 get_adaptive_decay_window(u32 congestion) {
    // Base 500ms, scale to 1.5s at max congestion
    u64 base = BASE_DECAY_WINDOW_NS;
    u64 window = base + (1000000000ULL * congestion) / 1000;  // add 0-1s
    return (window > 1500000000ULL) ? 1500000000ULL : window;
}

// -- Helper: Apply access count decay based on folio age and tier --
// Decays access_count if folio hasn't been accessed recently
// Returns the decayed access_count
static __always_inline u32 apply_access_count_decay(struct net_folio_metadata *meta,
                                                     u64 now, u32 congestion) {
    if (!meta || meta->access_count <= 1)
        return meta ? meta->access_count : 1;

    u64 age_ns = (now > meta->last_access_ts) ? (now - meta->last_access_ts) : 0;
    u64 decay_window = get_adaptive_decay_window(congestion);

    // Tier-specific decay sensitivity
    u64 tier_sensitivity = DECAY_SENSITIVITY_WARM;  // default
    if (meta->access_tier == 0)
        tier_sensitivity = DECAY_SENSITIVITY_COLD;
    else if (meta->access_tier == 2)
        tier_sensitivity = DECAY_SENSITIVITY_HOT;

    // Scale decay window by tier sensitivity
    u64 tier_decay_window = (decay_window * tier_sensitivity) / 1500ULL;

    // If age exceeds tier-specific decay window, decay access_count by 1
    if (age_ns > tier_decay_window) {
        u32 decayed_count = meta->access_count - 1;
        if (decayed_count < 1)
            decayed_count = 1;
        return decayed_count;
    }

    return meta->access_count;
}

// -- Helper: Compute tier-specific adaptive time windows based on network conditions --

// Cold tier: aggressive window, scales faster with congestion (30-200ms)
// During sustained bursts, tighten window to evict stale pages faster
static __always_inline u64 get_adaptive_recent_window_cold(u32 congestion) {
    // Base 30ms, scale to 200ms at max congestion
    // Scale factor: 5.67x from base at high congestion
    u64 base = 30000000ULL;   // 30ms base
    u64 window = base + (170000000ULL * congestion) / 1000;  // add 0-170ms
    if (window > 200000000ULL)
        window = 200000000ULL;

    // During sustained bursts, reduce window to evict cold pages more aggressively
    u32 burst_intensity = get_burst_intensity();
    if (burst_intensity >= 500) {  // moderate to heavy burst (8+ consecutive packets)
        // Reduce window by 30% during sustained bursts
        window = (window * 70) / 100;
    }

    return window;
}

// Warm tier: moderate window, moderate scale (80-400ms)
// During sustained bursts, moderately tighten window
static __always_inline u64 get_adaptive_recent_window_warm(u32 congestion) {
    // Base 80ms, scale to 400ms at max congestion
    u64 base = 80000000ULL;   // 80ms base
    u64 window = base + (320000000ULL * congestion) / 1000;  // add 0-320ms
    if (window > 400000000ULL)
        window = 400000000ULL;

    // During sustained bursts, reduce window by 20%
    u32 burst_intensity = get_burst_intensity();
    if (burst_intensity >= 250) {  // light to heavy burst (4+ consecutive packets)
        // Reduce window by 20% during sustained bursts
        window = (window * 80) / 100;
    }

    return window;
}

// Hot tier: conservative window, slow scale (100-500ms)
static __always_inline u64 get_adaptive_recent_window_hot(u32 congestion) {
    // Base 100ms, scale to 500ms at max congestion
    u64 base = 100000000ULL;  // 100ms base
    u64 window = base + (400000000ULL * congestion) / 1000;  // add 0-400ms
    return (window > 500000000ULL) ? 500000000ULL : window;
}

// Legacy unified window for compatibility (used in scoring)
static __always_inline u64 get_adaptive_recent_window(u32 congestion) {
    // Scale from BASE_RECENT_ACCESS_NS (50ms) to 150ms based on congestion
    // High congestion → wider window to protect recency
    u64 window = BASE_RECENT_ACCESS_NS;
    window += (BASE_RECENT_ACCESS_NS * congestion) / 1000;  // add 0-50ms
    return window;
}

static __always_inline u64 get_adaptive_working_set_window(u32 congestion) {
    // Scale from BASE_WORKING_SET_NS (800ms) to 2s based on congestion
    u64 window = BASE_WORKING_SET_NS;
    window += (BASE_WORKING_SET_NS * congestion) / 500;  // add 0-1.6s
    return (window > 2000000000ULL) ? 2000000000ULL : window;
}

// -- Helper: Compute folio eviction score (higher = keep it) --
static __always_inline u32 compute_folio_score(struct net_folio_metadata *meta,
                                                u64 now, u32 congestion,
                                                bool in_burst, bool session_active) {
    u32 score = 0;

    if (!meta)
        return 0;

    u64 age_ns = (now > meta->last_access_ts) ? (now - meta->last_access_ts) : 0;
    u64 recent_window = get_adaptive_recent_window(congestion);
    u64 working_set_window = get_adaptive_working_set_window(congestion);

    // Recency score (0-500 points)
    // Linear decay from 500 (just accessed) to 0 (beyond recent window)
    if (age_ns < recent_window) {
        score += 500 - (500 * age_ns) / recent_window;
    }

    // Frequency score (0-300 points) — now uses decayed access_count
    u32 decayed_count = apply_access_count_decay(meta, now, congestion);
    if (decayed_count >= 4)
        score += 300;
    else if (decayed_count == 3)
        score += 150;
    else if (decayed_count == 2)
        score += 100;
    else if (decayed_count == 1)
        score += 50;

    // Burst protection bonus (0-200 points)
    // During bursts, protect the working set more aggressively
    if (in_burst && age_ns < working_set_window) {
        score += 200 - (200 * age_ns) / working_set_window;
    }

    // Congestion protection (0-100 points)
    // In high congestion, protect pages in working set more
    if (session_active && age_ns < working_set_window && congestion > 500) {
        score += (congestion - 500) / 5;  // 0-100 points
    }

    // Tier bonus: hot folios get extra protection
    if (meta->access_tier == 2)
        score += 150;
    else if (meta->access_tier == 1)
        score += 75;

    return score;
}

// -- Eviction callback for cold_list (most aggressive eviction) --
static int bpf_evict_cold_cb(int idx, struct cache_ext_list_node *node) {
    u64 now = bpf_ktime_get_ns();

    // Update burst tracking based on network activity
    update_burst_tracking(now);

    u64 key = (u64)node->folio;

    struct net_folio_metadata *meta =
        bpf_map_lookup_elem(&folio_metadata_map, &key);

    if (!meta)
        return CACHE_EXT_EVICT_NODE;

    if (folio_test_dirty(node->folio) || folio_test_writeback(node->folio))
        return CACHE_EXT_CONTINUE_ITER;

    // Cold list: use tier-specific aggressive recency window
    // Scales faster than warm/hot to evict cold pages efficiently
    u32 congestion = compute_congestion_score();
    u64 cold_recent_window = get_adaptive_recent_window_cold(congestion);

    if (meta->access_tier == 0) {
        u64 age_ns = (now > meta->last_access_ts) ?
            (now - meta->last_access_ts) : 0;
        // Evict if older than the tier-specific adaptive window
        if (age_ns > cold_recent_window)
            return CACHE_EXT_EVICT_NODE;
    }

    return CACHE_EXT_CONTINUE_ITER;
}

// -- Eviction callback for warm_list (moderate eviction) --
static int bpf_evict_warm_cb(int idx, struct cache_ext_list_node *node) {
    u64 now = bpf_ktime_get_ns();
    u64 key = (u64)node->folio;

    struct net_folio_metadata *meta =
        bpf_map_lookup_elem(&folio_metadata_map, &key);

    if (!meta)
        return CACHE_EXT_EVICT_NODE;

    if (folio_test_dirty(node->folio) || folio_test_writeback(node->folio))
        return CACHE_EXT_CONTINUE_ITER;

    u32 congestion = compute_congestion_score();
    bool session_active = (now - last_packet_ts) < NET_IDLE_TIMEOUT_NS;
    bool in_burst = is_burst(now);

    // For warm list, also consider tier-specific recency window
    u64 warm_recent_window = get_adaptive_recent_window_warm(congestion);
    u64 age_ns = (now > meta->last_access_ts) ? (now - meta->last_access_ts) : 0;

    // Additional protection: don't evict warm folios within their tier-specific window
    if (age_ns < warm_recent_window)
        return CACHE_EXT_CONTINUE_ITER;

    u32 score = compute_folio_score(meta, now, congestion, in_burst, session_active);

    // Evict warm folios with low score (but not if within their recency window)
    if (score < 200)
        return CACHE_EXT_EVICT_NODE;

    return CACHE_EXT_CONTINUE_ITER;
}

// -- Eviction callback for hot_list (conservative eviction) --
static int bpf_evict_hot_cb(int idx, struct cache_ext_list_node *node) {
    u64 now = bpf_ktime_get_ns();
    u64 key = (u64)node->folio;

    struct net_folio_metadata *meta =
        bpf_map_lookup_elem(&folio_metadata_map, &key);

    if (!meta)
        return CACHE_EXT_EVICT_NODE;

    if (folio_test_dirty(node->folio) || folio_test_writeback(node->folio))
        return CACHE_EXT_CONTINUE_ITER;

    u32 congestion = compute_congestion_score();
    bool session_active = (now - last_packet_ts) < NET_IDLE_TIMEOUT_NS;
    bool in_burst = is_burst(now);

    // For hot list, use conservative hot-specific recency window
    u64 hot_recent_window = get_adaptive_recent_window_hot(congestion);
    u64 age_ns = (now > meta->last_access_ts) ? (now - meta->last_access_ts) : 0;

    // Strong protection: never evict hot folios within their tier-specific window
    if (age_ns < hot_recent_window)
        return CACHE_EXT_CONTINUE_ITER;

    u32 score = compute_folio_score(meta, now, congestion, in_burst, session_active);

    // Only evict hot folios with very low score (highly protective)
    if (score < 100)
        return CACHE_EXT_EVICT_NODE;

    return CACHE_EXT_CONTINUE_ITER;
}

// -- struct_ops: init ---------------------------------------------------------
s32 BPF_STRUCT_OPS_SLEEPABLE(evolved_init, struct mem_cgroup *memcg)
{
    hot_list = bpf_cache_ext_ds_registry_new_list(memcg);
    if (!hot_list)
        return -1;

    warm_list = bpf_cache_ext_ds_registry_new_list(memcg);
    if (!warm_list)
        return -1;

    cold_list = bpf_cache_ext_ds_registry_new_list(memcg);
    if (!cold_list)
        return -1;

    return 0;
}

// -- struct_ops: evict_folios -------------------------------------------------
void BPF_STRUCT_OPS(evolved_evict_folios,
                    struct cache_ext_eviction_ctx *eviction_ctx,
                    struct mem_cgroup *memcg)
{
    bump_counter(0);

    // Evict from cold list first (most aggressive)
    bpf_cache_ext_list_iterate(memcg, cold_list, bpf_evict_cold_cb, eviction_ctx);

    // Then warm list
    bpf_cache_ext_list_iterate(memcg, warm_list, bpf_evict_warm_cb, eviction_ctx);

    // Finally hot list (most conservative)
    bpf_cache_ext_list_iterate(memcg, hot_list, bpf_evict_hot_cb, eviction_ctx);
}

// -- struct_ops: folio_added --------------------------------------------------
void BPF_STRUCT_OPS(evolved_folio_added, struct folio *folio)
{
    if (!is_folio_relevant(folio))
        return;

    u64 key = (u64)folio;

    // Add new folios to cold list (FIFO tail)
    int ret = bpf_cache_ext_list_add_tail(cold_list, folio);
    if (ret != 0) {
        bump_counter(1);
        return;
    }

    // Initialize metadata
    struct net_folio_metadata new_meta = {
        .last_access_ts = bpf_ktime_get_ns(),
        .access_count  = 1,
        .access_tier   = 0,  // cold
    };
    bpf_map_update_elem(&folio_metadata_map, &key, &new_meta, BPF_ANY);
    bump_counter(2);
}

// -- struct_ops: folio_accessed -----------------------------------------------
void BPF_STRUCT_OPS(evolved_folio_accessed, struct folio *folio)
{
    if (!is_folio_relevant(folio))
        return;

    u64 key = (u64)folio;
    u64 now = bpf_ktime_get_ns();

    struct net_folio_metadata *meta =
        bpf_map_lookup_elem(&folio_metadata_map, &key);

    if (!meta) {
        // First access: add to cold list
        bpf_cache_ext_list_add_tail(cold_list, folio);
        struct net_folio_metadata new_meta = {
            .last_access_ts = now,
            .access_count  = 1,
            .access_tier   = 0,
        };
        bpf_map_update_elem(&folio_metadata_map, &key, &new_meta, BPF_ANY);
        bump_counter(3);
        return;
    }

    // Apply decay to access_count based on current congestion and age
    u32 congestion = compute_congestion_score();
    u32 decayed_count = apply_access_count_decay(meta, now, congestion);

    // Update metadata
    meta->last_access_ts = now;
    meta->access_count = decayed_count + 1;  // increment after decay

    // Determine new tier based on access count (after decay + increment)
    u32 old_tier = meta->access_tier;
    if (meta->access_count >= HOT_ACCESS_THRESHOLD)
        meta->access_tier = 2;  // hot
    else if (meta->access_count >= 2)
        meta->access_tier = 1;  // warm
    else
        meta->access_tier = 0;  // cold

    // Promote folio if tier changed
    if (meta->access_tier > old_tier) {
        // Remove from current list
        bpf_cache_ext_list_del(folio);

        // Add to appropriate new list
        if (meta->access_tier == 2) {
            bpf_cache_ext_list_add(hot_list, folio);  // hot at head
        } else if (meta->access_tier == 1) {
            bpf_cache_ext_list_add(warm_list, folio);  // warm at head
        }
    } else {
        // Same tier: move to head (MRU position)
        if (meta->access_tier == 2)
            bpf_cache_ext_list_move(hot_list, folio, false);
        else if (meta->access_tier == 1)
            bpf_cache_ext_list_move(warm_list, folio, false);
        else
            bpf_cache_ext_list_move(cold_list, folio, false);
    }

    bump_counter(4);
}

// -- struct_ops: folio_evicted ------------------------------------------------
void BPF_STRUCT_OPS(evolved_folio_evicted, struct folio *folio)
{
    if (!is_folio_relevant(folio))
        return;

    // Remove from the appropriate list
    bpf_cache_ext_list_del(folio);

    u64 key = (u64)folio;
    bpf_map_delete_elem(&folio_metadata_map, &key);
    bump_counter(5);
}

