        bump_counter(3);
        return;
    }

    // Apply decay to access_count based on current congestion, age, and session state
    u32 congestion = compute_congestion_score();
    bool in_burst = is_burst(now);
    bool session_active = (now - last_packet_ts) < NET_IDLE_TIMEOUT_NS;
    u32 decayed_count = apply_access_count_decay(meta, now, congestion, in_burst, session_active);

    // Update metadata
    meta->last_access_ts = now;
    meta->access_count = decayed_count + 1;  // increment after decay

    // Determine congestion-adaptive tier promotion thresholds
    // High congestion → lower thresholds (faster promotion to protect working set)
    // Low congestion → higher thresholds (more selective, aggressive eviction)
    u32 warm_threshold, hot_threshold;
    if (congestion > 700) {
        // Extreme congestion: very aggressive promotion
        warm_threshold = 1;
        hot_threshold = 2;
    } else if (congestion > 400) {
        // Moderate congestion: standard thresholds
        warm_threshold = 2;
        hot_threshold = 4;
    } else {
        // Low congestion: conservative promotion (more aggressive eviction)
        warm_threshold = 3;
        hot_threshold = 5;
    }

    // Determine new tier based on adaptive thresholds
    u32 old_tier = meta->access_tier;
    if (meta->access_count >= hot_threshold)
        meta->access_tier = 2;  // hot
    else if (meta->access_count >= warm_threshold)
        meta->access_tier = 1;  // warm
    else
        meta->access_tier = 0;  // cold

    // Promote folio if tier changed
    if (meta->access_tier > old_tier) {
        // Remove from current list
        bpf_cache_ext_list_del(folio);

        // Add to appropriate new list
        if (meta->access_tier == 2) {
            bpf_cache_ext_list_add(hot_list, folio);  // hot at head
        } else if (meta->access_tier == 1) {
            bpf_cache_ext_list_add(warm_list, folio);  // warm at head
        }
    } else {
        // Same tier: move to head (MRU position)
        if (meta->access_tier == 2)
            bpf_cache_ext_list_move(hot_list, folio, false);
        else if (meta->access_tier == 1)
            bpf_cache_ext_list_move(warm_list, folio, false);
        else
            bpf_cache_ext_list_move(cold_list, folio, false);
    }

    bump_counter(4);
}

